package com.ecommerce.service;
import com.ecommerce.dto.CatalogDtos.*; import com.ecommerce.exception.ApiException; import com.ecommerce.model.*; import com.ecommerce.repository.*; import org.springframework.cache.annotation.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.List;
@Service public class CatalogService { private final CategoryRepository categories; private final ProductRepository products; private final SlugService slugs; public CatalogService(CategoryRepository categories,ProductRepository products,SlugService slugs){this.categories=categories;this.products=products;this.slugs=slugs;} @org.springframework.transaction.annotation.Transactional(readOnly = true) @Cacheable("categories") public List<CategoryResponse> categories(){ return categories.findAll().stream().map(this::toCategoryResponse).toList(); } @org.springframework.transaction.annotation.Transactional(readOnly = true) @Cacheable(value="products",key="#categorySlug ?: 'all'") public List<ProductResponse> products(String categorySlug){ List<Product> p=(categorySlug==null||categorySlug.isBlank())?products.findByActiveTrue():products.findByActiveTrueAndCategorySlug(categorySlug); return p.stream().map(this::toProductResponse).toList(); } @org.springframework.transaction.annotation.Transactional(readOnly = true) public List<ProductResponse> search(String keyword){ return products.findByNameContainingIgnoreCaseAndActiveTrue(keyword).stream().map(this::toProductResponse).toList(); } @org.springframework.transaction.annotation.Transactional(readOnly = true) public ProductResponse product(Long id){ Product p=products.findById(id).filter(Product::isActive).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Product not found")); return toProductResponse(p); } @Transactional @CacheEvict(value={"products","categories"},allEntries=true) public CategoryResponse createCategory(CategoryRequest r){ String slug=slugs.slugify(r.name()); if(categories.existsBySlug(slug)) throw new ApiException(HttpStatus.CONFLICT,"Category already exists"); Category c=new Category(); c.setName(r.name()); c.setSlug(slug); c.setDescription(r.description()); return toCategoryResponse(categories.save(c)); } @Transactional @CacheEvict(value="products",allEntries=true) public ProductResponse createProduct(ProductRequest r){ if(products.existsBySku(r.sku())) throw new ApiException(HttpStatus.CONFLICT,"SKU already exists"); Product p=new Product(); apply(p,r); return toProductResponse(products.save(p)); } @Transactional @CacheEvict(value="products",allEntries=true) public ProductResponse updateProduct(Long id,ProductRequest r){ Product p=products.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Product not found")); products.findBySku(r.sku()).filter(e->!e.getId().equals(id)).ifPresent(e->{throw new ApiException(HttpStatus.CONFLICT,"SKU already exists");}); apply(p,r); return toProductResponse(p); } private void apply(Product p,ProductRequest r){ Category c=categories.findById(r.categoryId()).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Category not found")); p.setName(r.name()); p.setSku(r.sku()); p.setDescription(r.description()); p.setPrice(r.price()); p.setStockQuantity(r.stockQuantity()); p.setCategory(c); p.setActive(r.active()); } public CategoryResponse toCategoryResponse(Category c){ return new CategoryResponse(c.getId(),c.getName(),c.getSlug(),c.getDescription()); } public ProductResponse toProductResponse(Product p){ return new ProductResponse(p.getId(),p.getName(),p.getSku(),p.getDescription(),p.getPrice(),p.getStockQuantity(),p.isActive(),toCategoryResponse(p.getCategory())); } }